1	/**
2	 * Shared helpers for E2E tests.
3	 *
4	 * Canonical entry point: `mix test.e2e`, which boots the readaloud
5	 * release in a NixOS VM, seeds the fixture book via
6	 * `ReadaloudAudiobook.Fixtures.E2E.seed!/1`, and runs this suite
7	 * against http://localhost:4000 with BOOK_ID=1.
8	 *
9	 * Configurable via env vars (override when running outside the VM):
10	 *   BASE_URL  - server URL (default: http://localhost:4000)
11	 *   HEADLESS  - "false" to show the browser (default: true)
12	 *   BOOK_ID   - book ID to test with (default: 1)
13	 */
14	import puppeteer from "puppeteer";
15	
16	export const BASE_URL = process.env.BASE_URL || "http://localhost:4000";
17	export const BOOK_ID = process.env.BOOK_ID || "1";
18	export const HEADLESS = process.env.HEADLESS !== "false";
19	
20	/** Launch browser + page with sensible defaults. */
21	export async function setup() {
22		const browser = await puppeteer.launch({
23			headless: HEADLESS,
24			args: ["--no-sandbox", "--disable-setuid-sandbox"],
25		});
26		const page = await browser.newPage();
27		await page.setViewport({ width: 1280, height: 800 });
28		return { browser, page };
29	}
30	
31	/** Close the browser. */
32	export async function teardown(browser) {
33		await browser.close();
34	}
35	
36	/**
37	 * Navigate to a reader chapter page and wait for LiveView to mount AND
38	 * finish its first render cycle.
39	 *
40	 * Waits for three signals in order:
41	 *   1. networkidle2 — initial HTML loaded
42	 *   2. [data-phx-session] — LiveView socket connected
43	 *   3. #chapter-text — first post-mount render committed to the DOM
44	 *
45	 * Without (3), elements gated by mount-time assigns (#audio-player,
46	 * #speed-badge, etc.) can race the test's first `page.$()` and the
47	 * test fails with a misleading "selector not found" error. Tests that
48	 * need a specific element (e.g. #audio-player when audio_state is :ready)
49	 * should still `waitForSelector` it explicitly — openReader only
50	 * guarantees the chapter has rendered.
51	 */
52	export async function openReader(page, { bookId, chapterId } = {}) {
53		const bid = bookId || BOOK_ID;
54		// If no chapterId given, go to the book page first and grab the first chapter link
55		if (!chapterId) {
56			await page.goto(`${BASE_URL}/books/${bid}`, { waitUntil: "networkidle2" });
57			// Find the first "Read" link that points to /books/:id/read/:chapter_id
58			const href = await page.evaluate((id) => {
59				const link = document.querySelector(`a[href*="/books/${id}/read/"]`);
60				return link ? link.getAttribute("href") : null;
61			}, bid);
62			if (!href) throw new Error(`No chapter link found for book ${bid}`);
63			chapterId = href.match(/\/read\/(\d+)/)?.[1];
64		}
65		const url = `${BASE_URL}/books/${bid}/read/${chapterId}?nav=internal`;
66		await page.goto(url, { waitUntil: "networkidle2" });
67		await page.waitForSelector("[data-phx-session]", { timeout: 10000 });
68		await page.waitForSelector("#chapter-text", { timeout: 10000 });
69		return { bookId: bid, chapterId };
70	}
71	
72	/** Trigger the floating pill to show (mouse move on desktop). */
73	export async function showPill(page) {
74		await page.mouse.move(640, 400);
75		await page.mouse.move(641, 401);
76		// Wait for opacity transition
77		await page.waitForSelector("#floating-pill.opacity-100", { timeout: 5000 });
78	}
79	
80	/** Open the settings popover via the gear button. */
81	export async function openSettings(page) {
82		await showPill(page);
83		// `#floating-pill button[phx-click]` would match prev/next/gear and
84		// hit the first one in DOM order (prev). Walk the buttons explicitly
85		// and click the one that contains a hero-cog icon span — robust
86		// across :has()-support quirks and DOM ordering changes.
87		const gearHandle = await page.evaluateHandle(() => {
88			const pill = document.getElementById("floating-pill");
89			if (!pill) return null;
90			for (const btn of pill.querySelectorAll("button")) {
91				if (btn.querySelector('[class*="hero-cog"]')) return btn;
92			}
93			return null;
94		});
95		const isElement = await gearHandle.evaluate((el) => el !== null);
96		if (!isElement) {
97			throw new Error("openSettings: gear button (hero-cog) not found in pill");
98		}
99		// Already open? `JS.toggle` would close it. Skip the click in that
100		// case — tests call openSettings repeatedly across describe blocks.
101		const alreadyOpen = await page.evaluate(() => {
102			const el = document.getElementById("reader-settings");
103			return el ? getComputedStyle(el).display !== "none" : false;
104		});
105		if (alreadyOpen) return;
106		// Click via puppeteer's API so we get a real CDP click event that
107		// Phoenix LV's phx-click handler responds to (synthetic `el.click()`
108		// can race the LV command pipeline).
109		await gearHandle.click();
110		// `JS.toggle` flips the inline `display` style — it does NOT remove
111		// the Tailwind `hidden` class (Tailwind's `display: none` is overridden
112		// by the inline `display: block`, so `:not(.hidden)` would never match).
113		// Wait on the actual visibility instead.
114		await page.waitForFunction(
115			() => {
116				const el = document.getElementById("reader-settings");
117				return el && getComputedStyle(el).display !== "none";
118			},
119			{ timeout: 3000 },
120		);
121	}
122	
123	/** Get all chapter IDs for a book by reading the chapter bar data attribute. */
124	export async function getChapters(page) {
125		return page.evaluate(() => {
126			const bar = document.getElementById("chapter-bar");
127			if (!bar) return [];
128			return JSON.parse(bar.dataset.chapters);
129		});
130	}
