1	/**
2	 * Reload-guard regression: LiveView's hard-reload recovery must not kill
3	 * background audio playback.
4	 *
5	 * Reproduces the 2026-06-10 production incident (book 12, ch 820→821,
6	 * reconstructed from the [player] diagnostics channel):
7	 *
8	 *   - Phone screen locked, audio playing. The OS silently suspends the
9	 *     tab's network: the LV WebSocket is dead but the client doesn't
10	 *     know it yet (no FIN arrives — a "zombie" socket).
11	 *   - Chapter ends. The hook's client-owned advance works perfectly:
12	 *     swap to the prefetched blob, audio.play() OK, pushState URL.
13	 *   - The hook also calls pushEvent("next_chapter"). The channel still
14	 *     believes it's connected, so the push goes into the void and times
15	 *     out after PUSH_TIMEOUT (30s).
16	 *   - phoenix_live_view's recovery for a push timeout (view.js
17	 *     pushWithReply) is liveSocket.reloadWithJitter → 5-10s jitter →
18	 *     window.location.reload(). Join errors and close-1000 failsafe
19	 *     converge on the same path.
20	 *   - The reload destroys the playing blob audio mid-chapter, loses the
21	 *     autoplay gesture, and the fresh page mounts paused at 0:00. The
22	 *     suspended tab then aborts its own audio preloads and goes dark —
23	 *     the user wakes the phone to silence and "could not connect".
24	 *
25	 * Invariant this test pins: while the page is hidden and the reader
26	 * audio is actively playing, reloadWithJitter must NOT reload the page.
27	 * Once the page is visible again with a healthy socket, no reload
28	 * happens either (recovery is rejoin, not reload).
29	 */
30	import { describe, it, before, after } from "node:test";
31	import assert from "node:assert";
32	import { setup, teardown, openReader } from "../helpers.js";
33	
34	// Stock reloadWithJitter fires after RELOAD_JITTER_MIN..MAX (5-10s).
35	// Wait past the max plus slack to prove the reload did not happen.
36	const JITTER_MAX_MS = 10_000;
37	const SLACK_MS = 3_000;
38	
39	describe("Background-audio reload guard", () => {
40		let browser, page;
41	
42		before(async () => {
43			({ browser, page } = await setup());
44			await openReader(page);
45			await page.waitForSelector("#audio-element", { timeout: 10000 });
46			await page.waitForFunction(
47				() => {
48					const a = document.getElementById("audio-element");
49					return a?.src && a.src.includes("/api/books/");
50				},
51				{ timeout: 5000 },
52			);
53		});
54	
55		after(async () => {
56			await teardown(browser);
57		});
58	
59		it("defers LV's hard-reload recovery while hidden audio is playing", async () => {
60			// Start playback. Muted so headless Chrome's autoplay policy
61			// allows it without a gesture — the guard only cares about
62			// `!audio.paused`.
63			await page.evaluate(async () => {
64				const a = document.getElementById("audio-element");
65				a.muted = true;
66				await a.play();
67			});
68	
69			// Emulate the locked screen: visibilityState becomes "hidden".
70			// Plant a marker that a page reload would wipe.
71			await page.evaluate(() => {
72				window.__reloadGuardMarker = true;
73				Object.defineProperty(document, "visibilityState", {
74					value: "hidden",
75					configurable: true,
76				});
77				Object.defineProperty(document, "hidden", {
78					value: true,
79					configurable: true,
80				});
81				document.dispatchEvent(new Event("visibilitychange"));
82			});
83	
84			// Trigger the recovery path all three production triggers (push
85			// timeout, join error, close-1000 failsafe) converge on.
86			await page.evaluate(() => {
87				window.liveSocket.reloadWithJitter(window.liveSocket.main);
88			});
89	
90			// Stock behavior: view.destroy() + window.location.reload() within
91			// 5-10s. Wait past that window.
92			await new Promise((r) => setTimeout(r, JITTER_MAX_MS + SLACK_MS));
93	
94			const afterHidden = await page.evaluate(() => ({
95				marker: window.__reloadGuardMarker === true,
96				audioPlaying: (() => {
97					const a = document.getElementById("audio-element");
98					return !!a && !a.paused;
99				})(),
100			}));
101	
102			assert.ok(
103				afterHidden.marker,
104				"Page reloaded while hidden audio was playing — LV's " +
105					"reloadWithJitter recovery killed the background listening " +
106					"session (the 2026-06-10 incident). The reload must be " +
107					"deferred until the page is visible again.",
108			);
109			assert.ok(
110				afterHidden.audioPlaying,
111				"Audio element stopped playing during the hidden window.",
112			);
113	
114			// Screen comes back on. The socket here is healthy (we never
115			// actually broke it), so the deferred reload must be skipped —
116			// recovery is rejoin, not reload.
117			await page.evaluate(() => {
118				Object.defineProperty(document, "visibilityState", {
119					value: "visible",
120					configurable: true,
121				});
122				Object.defineProperty(document, "hidden", {
123					value: false,
124					configurable: true,
125				});
126				document.dispatchEvent(new Event("visibilitychange"));
127			});
128	
129			// Reconnect grace (4s) plus slack.
130			await new Promise((r) => setTimeout(r, 6_000));
131	
132			const afterVisible = await page.evaluate(() => ({
133				marker: window.__reloadGuardMarker === true,
134				socketConnected: window.liveSocket.isConnected(),
135			}));
136	
137			assert.ok(
138				afterVisible.socketConnected,
139				"sanity: socket should still be connected in this scenario",
140			);
141			assert.ok(
142				afterVisible.marker,
143				"Page reloaded after becoming visible even though the socket " +
144					"was connected — the deferred reload must be skipped when " +
145					"the socket has recovered.",
146			);
147		});
148	});
