/**
 * Shared helpers for E2E tests.
 *
 * Canonical entry point: `mix test.e2e`, which boots the readaloud
 * release in a NixOS VM, seeds the fixture book via
 * `ReadaloudAudiobook.Fixtures.E2E.seed!/1`, and runs this suite
 * against http://localhost:4000 with BOOK_ID=1.
 *
 * Configurable via env vars (override when running outside the VM):
 *   BASE_URL  - server URL (default: http://localhost:4000)
 *   HEADLESS  - "false" to show the browser (default: true)
 *   BOOK_ID   - book ID to test with (default: 1)
 */
import puppeteer from "puppeteer";

export const BASE_URL = process.env.BASE_URL || "http://localhost:4000";
export const BOOK_ID = process.env.BOOK_ID || "1";
export const HEADLESS = process.env.HEADLESS !== "false";

/** Launch browser + page with sensible defaults. */
export async function setup() {
	const browser = await puppeteer.launch({
		headless: HEADLESS,
		args: ["--no-sandbox", "--disable-setuid-sandbox"],
	});
	const page = await browser.newPage();
	await page.setViewport({ width: 1280, height: 800 });
	return { browser, page };
}

/** Close the browser. */
export async function teardown(browser) {
	await browser.close();
}

/**
 * Navigate to a reader chapter page and wait for LiveView to mount AND
 * connect its socket.
 *
 * Waits for three signals in order:
 *   1. domcontentloaded — initial (dead-render) HTML parsed
 *   2. [data-phx-session].phx-connected — LiveView socket joined
 *   3. #chapter-text — chapter content present in the DOM
 *
 * (2) is the load-bearing one: [data-phx-session] and #chapter-text
 * both exist in the dead render, but phx-click/pushEvent interactions
 * race the socket join without it. domcontentloaded + .phx-connected is
 * both faster (no 500ms networkidle heuristic per navigation) and a
 * stronger guarantee than the old networkidle2 wait. Tests that need a
 * specific element (e.g. #audio-player when audio_state is :ready)
 * should still `waitForSelector` it explicitly — openReader only
 * guarantees the chapter has rendered and the LV is live.
 */
export async function openReader(page, { bookId, chapterId } = {}) {
	const bid = bookId || BOOK_ID;
	// If no chapterId given, go to the book page first and grab the first chapter link
	if (!chapterId) {
		await page.goto(`${BASE_URL}/books/${bid}`, {
			waitUntil: "domcontentloaded",
		});
		// Find the first "Read" link that points to /books/:id/read/:chapter_id
		const href = await page.evaluate((id) => {
			const link = document.querySelector(`a[href*="/books/${id}/read/"]`);
			return link ? link.getAttribute("href") : null;
		}, bid);
		if (!href) throw new Error(`No chapter link found for book ${bid}`);
		chapterId = href.match(/\/read\/(\d+)/)?.[1];
	}
	const url = `${BASE_URL}/books/${bid}/read/${chapterId}?nav=internal`;
	await page.goto(url, { waitUntil: "domcontentloaded" });
	await page.waitForSelector("[data-phx-session].phx-connected", {
		timeout: 10000,
	});
	await page.waitForSelector("#chapter-text", { timeout: 10000 });
	return { bookId: bid, chapterId };
}

/** Trigger the floating pill to show (mouse move on desktop). */
export async function showPill(page) {
	await page.mouse.move(640, 400);
	await page.mouse.move(641, 401);
	// Wait for opacity transition
	await page.waitForSelector("#floating-pill.opacity-100", { timeout: 5000 });
}

/** Open the settings popover via the gear button. */
export async function openSettings(page) {
	await showPill(page);
	// `#floating-pill button[phx-click]` would match prev/next/gear and
	// hit the first one in DOM order (prev). Walk the buttons explicitly
	// and click the one that contains a hero-cog icon span — robust
	// across :has()-support quirks and DOM ordering changes.
	const gearHandle = await page.evaluateHandle(() => {
		const pill = document.getElementById("floating-pill");
		if (!pill) return null;
		for (const btn of pill.querySelectorAll("button")) {
			if (btn.querySelector('[class*="hero-cog"]')) return btn;
		}
		return null;
	});
	const isElement = await gearHandle.evaluate((el) => el !== null);
	if (!isElement) {
		throw new Error("openSettings: gear button (hero-cog) not found in pill");
	}
	// Already open? `JS.toggle` would close it. Skip the click in that
	// case — tests call openSettings repeatedly across describe blocks.
	const alreadyOpen = await page.evaluate(() => {
		const el = document.getElementById("reader-settings");
		return el ? getComputedStyle(el).display !== "none" : false;
	});
	if (alreadyOpen) return;
	// Click via puppeteer's API so we get a real CDP click event that
	// Phoenix LV's phx-click handler responds to (synthetic `el.click()`
	// can race the LV command pipeline).
	await gearHandle.click();
	// `JS.toggle` flips the inline `display` style — it does NOT remove
	// the Tailwind `hidden` class (Tailwind's `display: none` is overridden
	// by the inline `display: block`, so `:not(.hidden)` would never match).
	// Wait on the actual visibility instead.
	await page.waitForFunction(
		() => {
			const el = document.getElementById("reader-settings");
			return el && getComputedStyle(el).display !== "none";
		},
		{ timeout: 3000 },
	);
}

/** Get all chapter IDs for a book by reading the chapter bar data attribute. */
export async function getChapters(page) {
	return page.evaluate(() => {
		const bar = document.getElementById("chapter-bar");
		if (!bar) return [];
		return JSON.parse(bar.dataset.chapters);
	});
}

# NixOS VM test that starts the readaloud service, seeds the canonical
# e2e fixture via a release rpc call, and runs the full puppeteer suite
# against it. Single source of truth for the fixture shape lives in
# `ReadaloudAudiobook.Fixtures.E2E.seed!/1` — this check just calls it.
{
  self,
  pkgs,
  package,
  readaloudModule,
}:
let
  # Pre-build node_modules for the e2e test suite.
  # This avoids running npm install inside the VM (no network access).
  #
  # src is just the npm manifest files — NOT the whole e2e/ dir — so
  # editing a test never invalidates this derivation and re-runs npm ci.
  e2eNpmSrc = pkgs.runCommand "readaloud-e2e-npm-src" { } ''
    mkdir $out
    cp ${self}/e2e/package.json ${self}/e2e/package-lock.json $out/
  '';
  e2eNodeModules = pkgs.buildNpmPackage {
    pname = "readaloud-e2e-deps";
    version = "0.1.0";
    src = e2eNpmSrc;

    npmDepsHash = "REDACTED";

    # Skip puppeteer's bundled chromium download — we provide system chromium
    env.PUPPETEER_SKIP_DOWNLOAD = "true";

    # We only need node_modules, not a build output
    dontNpmBuild = true;

    installPhase = ''
      runHook preInstall
      mkdir -p $out/lib
      cp -r node_modules $out/lib/node_modules
      runHook postInstall
    '';
  };

  secretKeyFile = pkgs.writeText "test-secret-key" "this-is-a-test-secret-key-base-that-is-at-least-sixty-four-bytes-long-for-phoenix";
in
pkgs.testers.nixosTest {
  name = "readaloud-e2e";

  nodes.server =
    { pkgs, ... }:
    {
      imports = [ readaloudModule ];

      services.readaloud = {
        enable = true;
        port = 4000;
        host = "localhost";
        secretKeyBaseFile = secretKeyFile;
      };

      # Chromium and Node.js for running puppeteer tests
      environment.systemPackages = with pkgs; [
        nodejs_22
        chromium
        sqlite
        curl
      ];

      # Puppeteer should use the system chromium, not download its own
      environment.variables.PUPPETEER_EXECUTABLE_PATH = "${pkgs.chromium}/bin/chromium";

      # VM resources — chromium needs decent memory, and per-file browser
      # launches + page renders are CPU-bound. The dev host has plenty of
      # headroom (24 cores / 62 GB); CI runners that don't will just
      # timeshare the vCPUs.
      virtualisation.memorySize = 8192;
      virtualisation.cores = 8;
    };

  testScript = ''
    server.wait_for_unit("readaloud.service")
    server.wait_for_open_port(4000)

    # Sanity: the service responds to HTTP before we touch the DB.
    server.succeed("curl -sf http://localhost:4000/ > /dev/null")

    # Seed the canonical e2e fixture via release rpc. This runs inside
    # the running BEAM node, so the writes share the service's view of
    # the filesystem (PrivateTmp namespace) and the SQLite pool.
    server.succeed(
        "runuser -u readaloud -- env "
        "RELEASE_COOKIE=readaloud "
        "HOME=/var/lib/readaloud "
        "${package}/bin/readaloud rpc "
        "'ReadaloudAudiobook.Fixtures.E2E.seed!()'"
    )

    # Verify seeded data — defensive sanity, not a substitute for the suite.
    server.succeed("sqlite3 /var/lib/readaloud/readaloud.db 'SELECT count(*) FROM books;' | grep -q '^1$'")
    server.succeed("sqlite3 /var/lib/readaloud/readaloud.db 'SELECT count(*) FROM chapters;' | grep -q '^3$'")
    server.succeed("sqlite3 /var/lib/readaloud/readaloud.db 'SELECT count(*) FROM chapter_audios;' | grep -q '^2$'")
    server.succeed("curl -sf http://localhost:4000/books/1 | grep -q 'Chapter 1'")

    # Set up the e2e test directory with pre-built node_modules.
    server.succeed("cp -r ${self}/e2e /tmp/e2e")
    server.succeed("chmod -R u+w /tmp/e2e")
    server.succeed("ln -sf ${e2eNodeModules}/lib/node_modules /tmp/e2e/node_modules")

    # Run the full e2e suite. --test-reporter=spec surfaces skip
    # messages and per-test timing in the build log; the default 'tap'
    # reporter buries them.
    #
    # --test-concurrency=1 forces files to run sequentially. Files share
    # the BEAM/SQLite — accidental-navigation.test.js's modal triggers
    # are gated on `ReadingProgress` being a known chapter at a known
    # moment, which races horribly when reader-styles-persist or audio
    # tests rewrite progress in parallel. Sequential is ~2× slower but
    # deterministic, which is the tradeoff this suite is for.
    server.succeed(
        "cd /tmp/e2e && "
        "PUPPETEER_EXECUTABLE_PATH=\"${pkgs.chromium}/bin/chromium\" "
        "BASE_URL=\"http://localhost:4000\" "
        "BOOK_ID=\"1\" "
        "HEADLESS=\"true\" "
        "node --test --test-concurrency=1 --test-reporter=spec tests/*.test.js"
    )
  '';
}

